 "content": "def transform(grid):
    """Tile each nonzero input cell with the color on the zero positions of the input mask."""
    rows, cols = len(grid), len(grid[0])
    out = [[0] * (3 * cols) for _ in range(3 * rows)]
    for r in range(rows):
        for c in range(cols):
            value = grid[r][c]
            if value != 0:
                for mr in range(rows):
                    for mc in range(cols):
                        if grid[mr][mc] == 0:
                            out[3 * r + mr][3 * c + mc] = value
    return out

if __name__ == "__main__":
    demos = [
        ([[0, 7, 0], [7, 7, 7], [0, 7, 0]], [
